
.rose-lily {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-ink);
  border: 1px solid var(--c-line);
  color: var(--c-paper);
  font-family: var(--font-ui);
  font-size: 13px;
  line-height: 1.5;
  overflow: hidden;
}

.rose-lily::before {
  content: '';
  display: block;
  height: 2px;
  background: linear-gradient(90deg, var(--c-rose), var(--c-bronze) 48%, var(--c-lily));
  opacity: 0.8;
}

.cast {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  background: var(--c-line-soft);
}

@media (max-width: 560px) {
  .cast {
    grid-template-columns: minmax(0, 1fr);
  }
}
