
.antagonist {
  padding: 9px 12px 11px;
  border-top: 1px solid var(--c-line-soft);
  background: var(--c-ink);
}

.head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 7px;
}

.mark {
  width: 15px;
  height: 15px;
  flex: none;
  fill: none;
  stroke: var(--c-bronze);
  stroke-width: 1.4;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.role {
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--c-bronze);
}

.nights {
  padding: 0 6px;
  border: 1px solid var(--c-bronze-dim);
  font-size: 0.7rem;
  color: var(--c-paper-dim);
}

.value {
  margin-left: auto;
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--c-paper);
  font-variant-numeric: tabular-nums;
}

.goal {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-top: 7px;
}

.goal-caption {
  flex: none;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  color: var(--c-muted);
}

.goal-text {
  min-width: 0;
  font-size: 0.78rem;
  color: var(--c-paper-dim);
  overflow-wrap: anywhere;
}
