
.panel {
  padding: 9px 12px 11px;
  border-top: 1px solid var(--c-line-soft);
  background: var(--c-ink);
}

.head {
  display: flex;
  align-items: center;
  gap: 7px;
}

.mark {
  width: 15px;
  height: 15px;
  flex: none;
  fill: none;
  stroke: var(--c-bronze);
  stroke-width: 1.4;
  stroke-linejoin: round;
}

.title {
  font-size: 0.86rem;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.count {
  font-size: 0.72rem;
  color: var(--c-muted);
  font-variant-numeric: tabular-nums;
}

.list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 6px;
  max-height: 148px;
  margin-top: 8px;
  padding-right: 2px;
  overflow-y: auto;
  list-style: none;
}

.item {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  padding: 5px 8px;
  border: 1px solid var(--c-line-soft);
  border-left: 2px solid var(--c-bronze-dim);
  background: rgba(255, 255, 255, 0.02);
}

.item-name {
  font-size: 0.78rem;
  font-weight: 700;
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-muted);
  overflow-wrap: anywhere;
}

.empty {
  margin-top: 7px;
  font-size: 0.75rem;
  color: var(--c-muted);
}

@media (max-width: 560px) {
  .list {
    grid-template-columns: minmax(0, 1fr);
  }
}
