
.meter {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.meter[data-tone='rose'] {
  --m-accent: var(--c-rose);
  --m-accent-dim: var(--c-rose-dim);
}

.meter[data-tone='lily'] {
  --m-accent: var(--c-lily);
  --m-accent-dim: var(--c-lily-dim);
}

.meter[data-tone='bronze'] {
  --m-accent: var(--c-bronze);
  --m-accent-dim: var(--c-bronze-dim);
}

.meter[data-tone='ink'] {
  --m-accent: var(--c-paper-dim);
  --m-accent-dim: #3d332a;
}

.meter-label {
  flex: none;
  width: 28px;
  font-size: 0.7rem;
  letter-spacing: 0.05em;
  color: var(--c-muted);
}

.meter-track {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  height: 6px;
  background: var(--c-ink-3);
  border: 1px solid var(--c-line-soft);
  overflow: hidden;
}

.meter-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  background: linear-gradient(90deg, var(--m-accent-dim), var(--m-accent));
  transition: width 0.35s ease;
}

.meter-grid i {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  background: var(--c-ink);
  opacity: 0.75;
}

.meter-value {
  flex: none;
  min-width: 22px;
  text-align: right;
  font-size: 0.72rem;
  color: var(--c-paper-dim);
  font-variant-numeric: tabular-nums;
}

.meter[data-size='lg'] .meter-track {
  height: 10px;
}

.meter[data-size='lg'] .meter-value {
  font-size: 0.82rem;
  font-weight: 700;
  color: var(--c-paper);
}
