
.world {
  padding: 10px 12px 11px;
  border-bottom: 1px solid var(--c-line);
  background: linear-gradient(180deg, var(--c-ink-2), var(--c-ink));
}

.line {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 6px;
}

.date {
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  color: var(--c-paper);
}

.phase,
.place {
  color: var(--c-paper-dim);
}

.dot {
  color: var(--c-line);
}

.weather {
  margin-left: auto;
  padding: 0 6px;
  border: 1px solid var(--c-line-soft);
  font-size: 0.72rem;
  color: var(--c-muted);
}

.progress {
  display: flex;
  align-items: baseline;
  gap: 7px;
  margin-top: 7px;
}

.progress-caption {
  flex: none;
  font-size: 0.7rem;
  letter-spacing: 0.14em;
  color: var(--c-bronze);
}

.progress-text {
  font-size: 0.82rem;
  color: var(--c-paper);
  overflow-wrap: anywhere;
}

.events {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
  list-style: none;
}

.event {
  display: flex;
  flex-direction: column;
  flex: 1 1 156px;
  min-width: 0;
  padding: 5px 8px;
  border: 1px solid var(--c-line-soft);
  border-left: 2px solid var(--c-bronze);
  background: rgba(255, 255, 255, 0.02);
}

.event-title {
  font-size: 0.78rem;
  font-weight: 700;
}

.event-desc {
  font-size: 0.72rem;
  color: var(--c-muted);
  overflow-wrap: anywhere;
}
