
.heroine {
  padding: 10px 12px 12px;
  background: var(--c-ink);
}

.heroine[data-accent='rose'] {
  --c-accent: var(--c-rose);
  --c-accent-dim: var(--c-rose-dim);
}

.heroine[data-accent='lily'] {
  --c-accent: var(--c-lily);
  --c-accent-dim: var(--c-lily-dim);
}

.head {
  display: flex;
  align-items: center;
  gap: 6px;
}

.emblem {
  width: 15px;
  height: 15px;
  flex: none;
  fill: none;
  stroke: var(--c-accent);
  stroke-width: 1.4;
  stroke-linejoin: round;
}

.role {
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--c-accent);
}

.given {
  font-size: 0.72rem;
  color: var(--c-muted);
}

.stage {
  margin-left: auto;
  padding: 0 6px;
  border: 1px solid var(--c-accent-dim);
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  color: var(--c-paper-dim);
}

.fall {
  margin-top: 9px;
}

.stats {
  display: grid;
  gap: 4px;
  margin-top: 7px;
  list-style: none;
}

.facts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px 8px;
  margin-top: 9px;
}

.fact {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.fact.wide {
  grid-column: 1 / -1;
}

.fact dt {
  flex: none;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  color: var(--c-muted);
}

.fact dd {
  min-width: 0;
  font-size: 0.78rem;
  color: var(--c-paper-dim);
  overflow-wrap: anywhere;
}

.fact dd[data-on='true'] {
  font-weight: 700;
  color: var(--c-accent);
}

.outfit {
  margin-top: 9px;
  padding-top: 6px;
  border-top: 1px dashed var(--c-line-soft);
}

.outfit > summary {
  display: flex;
  align-items: center;
  gap: 6px;
  list-style: none;
  cursor: pointer;
}

.outfit > summary::-webkit-details-marker {
  display: none;
}

.outfit > summary::before {
  content: '';
  flex: none;
  width: 0;
  height: 0;
  border-left: 4px solid var(--c-muted);
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  transition: transform 0.2s ease;
}

.outfit[open] > summary::before {
  transform: rotate(90deg);
}

.outfit-caption {
  flex: none;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  color: var(--c-muted);
}

.outfit-brief {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 0.74rem;
  color: var(--c-paper-dim);
}

.outfit-list {
  display: grid;
  gap: 2px;
  margin-top: 6px;
  list-style: none;
}

.outfit-list li {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.outfit-list .part {
  flex: none;
  width: 30px;
  font-size: 0.7rem;
  color: var(--c-muted);
}

.outfit-list .value {
  min-width: 0;
  font-size: 0.74rem;
  color: var(--c-paper-dim);
  overflow-wrap: anywhere;
}
