
.protagonist {
  padding: 9px 12px 11px;
  border-top: 1px solid var(--c-line-soft);
  background: var(--c-ink);
}

.head {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 7px;
}

.mark {
  width: 15px;
  height: 15px;
  flex: none;
  fill: none;
  stroke: var(--c-paper-dim);
  stroke-width: 1.4;
  stroke-linejoin: round;
}

.role {
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--c-paper);
}

.mood {
  margin-left: auto;
  font-size: 0.76rem;
  color: var(--c-muted);
}

.stats {
  display: grid;
  gap: 4px;
  list-style: none;
}
